contracts/DFLIX.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DFLIX
 * @author Decentralflix — Phase 2
 * @notice The Decentralflix ERC20 token ("Decentralflix", symbol DFLIX, 18 decimals).
 *
 * Capabilities:
 * - Capped minting: accounts with MINTER_ROLE (granted by the admin) can mint,
 *   but total supply can never exceed MAX_SUPPLY (1,000,000,000 DFLIX).
 * - Staking: holders stake DFLIX for a minimum lock period (7 days) and accrue
 *   rewards from a reward pool at an admin-set rate.
 * - Seed-to-earn: the owner/attestor allocates rewards to seeders against
 *   off-chain seeding reports (identified by reportHash, replay-protected);
 *   seeders claim through the same claimRewards() path.
 *
 * ══════════════════════════════════════════════════════════════════════════
 *  REWARDS ARE PROTOCOL MECHANICS — NOT PROMISED YIELD.
 *  Staking rewards and seed-to-earn allocations are variable, pool-limited,
 *  and paid ONLY from the funded reward pool. Nothing here is a promise of
 *  yield, interest, profit, or any return on any contribution. The reward
 *  rate can be changed or set to zero by the admin at any time, the pool can
 *  run dry, and unclaimed accruals are bounded by what the pool holds.
 *  ANY MAINNET DEPLOYMENT MUST BE REVIEWED BY LICENSED COUNSEL FIRST
 *  (securities/Howey analysis, money-transmitter, tax, and consumer-law
 *  implications). This contract is provided for development/testing.
 * ══════════════════════════════════════════════════════════════════════════
 */
contract DFLIX is ERC20, AccessControl, ReentrancyGuard {
    /// @notice Role allowed to mint new tokens (granted/revoked by the admin).
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    /// @notice Absolute mint cap: 1 billion DFLIX (18 decimals).
    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 1e18;

    /// @notice Minimum time between a user's first stake and any unstake.
    uint256 public constant STAKE_LOCK_PERIOD = 7 days;

    /// @notice Staking reward rate: DFLIX per second per staked DFLIX, scaled by 1e18.
    /// E.g. 1e12 => 1e-6 DFLIX per staked DFLIX per second. Admin-settable, may be 0.
    uint256 public rewardPerTokenPerSecond;

    /// @notice DFLIX funded into the reward pool and not yet paid out.
    uint256 public rewardPool;

    /// @notice Address (besides the admin) allowed to allocate seed rewards.
    address public attestor;

    // Staking state
    mapping(address => uint256) public stakedBalance; // user => staked DFLIX
    mapping(address => uint256) public stakeLockStart; // user => first-stake timestamp
    mapping(address => uint256) private _rewardLastUpdate; // user => last accrual checkpoint
    mapping(address => uint256) private _accruedRewards; // user => checkpointed staking rewards

    // Seed-to-earn state
    mapping(address => uint256) public seedRewards; // seeder => allocated, unclaimed
    mapping(bytes32 => bool) public usedReportHashes; // reportHash => already allocated (replay guard)
    uint256 public allocatedSeedRewards; // total seed rewards allocated but not yet claimed

    // ── Errors ────────────────────────────────────────────────────────────
    error ExceedsMintCap(uint256 requested, uint256 maxSupply);
    error ZeroAmount();
    error ZeroAddress();
    error NotAuthorized(address caller);
    error InsufficientStake(uint256 requested, uint256 staked);
    error StakeLocked(uint256 unlockAt, uint256 nowTs);
    error NoRewardsToClaim(address user);
    error InsufficientRewardPool(uint256 needed, uint256 available);
    error DuplicateReport(bytes32 reportHash);
    error TransferFailed();

    // ── Events ────────────────────────────────────────────────────────────
    event RewardPoolFunded(address indexed funder, uint256 amount);
    event RewardRateUpdated(uint256 oldRate, uint256 newRate);
    event AttestorUpdated(address indexed oldAttestor, address indexed newAttestor);
    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event RewardsClaimed(
        address indexed user,
        uint256 total,
        uint256 stakingPart,
        uint256 seedPart
    );
    event SeedRewardAllocated(
        address indexed seeder,
        uint256 amount,
        bytes32 indexed reportHash
    );

    constructor() ERC20("Decentralflix", "DFLIX") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        attestor = msg.sender;
    }

    modifier onlyAdminOrAttestor() {
        if (!hasRole(DEFAULT_ADMIN_ROLE, msg.sender) && msg.sender != attestor) {
            revert NotAuthorized(msg.sender);
        }
        _;
    }

    // ── Minting ───────────────────────────────────────────────────────────

    /**
     * @notice Mint new DFLIX. Only callable by MINTER_ROLE; reverts if the mint
     * would push total supply above MAX_SUPPLY.
     */
    function mint(address to, uint256 amount) external onlyRole(MINTER_ROLE) {
        if (to == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        if (totalSupply() + amount > MAX_SUPPLY) {
            revert ExceedsMintCap(totalSupply() + amount, MAX_SUPPLY);
        }
        _mint(to, amount);
    }

    // ── Admin ─────────────────────────────────────────────────────────────

    /// @notice Replace the attestor allowed to allocate seed rewards.
    function setAttestor(address newAttestor) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (newAttestor == address(0)) revert ZeroAddress();
        address oldAttestor = attestor;
        attestor = newAttestor;
        emit AttestorUpdated(oldAttestor, newAttestor);
    }

    /**
     * @notice Set the staking reward rate (per-second, 1e18-scaled). May be set
     * to zero to stop new staking accrual (NOT a yield promise — see header).
     */
    function setRewardRate(uint256 newRate) external onlyRole(DEFAULT_ADMIN_ROLE) {
        uint256 oldRate = rewardPerTokenPerSecond;
        rewardPerTokenPerSecond = newRate;
        emit RewardRateUpdated(oldRate, newRate);
    }

    /**
     * @notice Fund the reward pool. Pulls `amount` DFLIX from the admin via
     * allowance. Rewards can only ever be paid out of this pool.
     */
    function fundRewardPool(uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (amount == 0) revert ZeroAmount();
        rewardPool += amount;
        bool ok = transferFrom(msg.sender, address(this), amount);
        if (!ok) revert TransferFailed();
        emit RewardPoolFunded(msg.sender, amount);
    }

    // ── Seed-to-earn ──────────────────────────────────────────────────────

    /**
     * @notice Allocate seed-to-earn rewards to a seeder against an off-chain
     * seeding report. Replay-protected by `reportHash`, and the total allocated
     * seed rewards can never exceed the funded pool (best-effort guard —
     * staking accruals are not pre-reserved against the pool).
     * @dev The seeder claims via claimRewards(). This is a protocol mechanic,
     * NOT promised yield (see header notice).
     */
    function allocateSeedReward(
        address seeder,
        uint256 amount,
        bytes32 reportHash
    ) external onlyAdminOrAttestor {
        if (seeder == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        if (usedReportHashes[reportHash]) revert DuplicateReport(reportHash);
        if (allocatedSeedRewards + amount > rewardPool) {
            revert InsufficientRewardPool(allocatedSeedRewards + amount, rewardPool);
        }

        usedReportHashes[reportHash] = true;
        allocatedSeedRewards += amount;
        seedRewards[seeder] += amount;

        emit SeedRewardAllocated(seeder, amount, reportHash);
    }

    // ── Staking ──────────────────────────────────────────────────────────

    /**
     * @notice Stake DFLIX. Requires prior approval. First stake starts the
     * user's lock clock; further stakes do not extend it.
     * @dev Accrues pending staking rewards up to this point before updating
     * the balance, so partial unstakes don't over-count.
     */
    function stake(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        _checkpoint(msg.sender);

        if (stakeLockStart[msg.sender] == 0) {
            stakeLockStart[msg.sender] = block.timestamp;
        }
        stakedBalance[msg.sender] += amount;

        bool ok = transferFrom(msg.sender, address(this), amount);
        if (!ok) revert TransferFailed();

        emit Staked(msg.sender, amount);
    }

    /**
     * @notice Unstake DFLIX. Blocked until STAKE_LOCK_PERIOD has passed since
     * the user's first stake. Pending staking rewards stay claimable via
     * claimRewards().
     */
    function unstake(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        uint256 staked = stakedBalance[msg.sender];
        if (amount > staked) revert InsufficientStake(amount, staked);

        uint256 unlockAt = stakeLockStart[msg.sender] + STAKE_LOCK_PERIOD;
        if (block.timestamp < unlockAt) revert StakeLocked(unlockAt, block.timestamp);

        _checkpoint(msg.sender);
        stakedBalance[msg.sender] = staked - amount;
        if (stakedBalance[msg.sender] == 0) {
            stakeLockStart[msg.sender] = 0;
        }

        _transfer(address(this), msg.sender, amount);

        emit Unstaked(msg.sender, amount);
    }

    /**
     * @notice Claim all pending rewards (accrued staking rewards + allocated
     * seed rewards) in one transfer. Reverts when there is nothing to claim or
     * when the pool cannot cover the claim.
     * @dev Rewards are protocol mechanics, NOT promised yield — see header.
     */
    function claimRewards() external nonReentrant {
        _checkpoint(msg.sender);

        uint256 stakingPart = _accruedRewards[msg.sender];
        uint256 seedPart = seedRewards[msg.sender];
        uint256 total = stakingPart + seedPart;
        if (total == 0) revert NoRewardsToClaim(msg.sender);
        if (total > rewardPool) revert InsufficientRewardPool(total, rewardPool);

        _accruedRewards[msg.sender] = 0;
        seedRewards[msg.sender] = 0;
        allocatedSeedRewards -= seedPart;
        rewardPool -= total;

        _transfer(address(this), msg.sender, total);

        emit RewardsClaimed(msg.sender, total, stakingPart, seedPart);
    }

    // ── Views ─────────────────────────────────────────────────────────────

    /**
     * @notice Pending rewards for `user`: checkpointed staking rewards plus
     * live accrual since the last checkpoint, plus unclaimed seed rewards.
     */
    function pendingRewards(address user)
        external
        view
        returns (
            uint256 stakingPart,
            uint256 seedPart,
            uint256 total
        )
    {
        stakingPart = _accruedRewards[user];
        uint256 staked = stakedBalance[user];
        if (staked > 0 && rewardPerTokenPerSecond > 0) {
            uint256 elapsed = block.timestamp - _rewardLastUpdate[user];
            stakingPart += (staked * rewardPerTokenPerSecond * elapsed) / 1e18;
        }
        seedPart = seedRewards[user];
        total = stakingPart + seedPart;
    }

    /// @notice Checkpointed (not live-accrued) staking rewards for `user`.
    function accruedRewards(address user) external view returns (uint256) {
        return _accruedRewards[user];
    }

    /// @notice Last accrual checkpoint timestamp for `user`.
    function rewardLastUpdate(address user) external view returns (uint256) {
        return _rewardLastUpdate[user];
    }

    // ── Internal ──────────────────────────────────────────────────────────

    /**
     * @dev Rolls live staking accrual into _accruedRewards[user] and stamps the
     * checkpoint time. Called before every stake/unstake/claim.
     */
    function _checkpoint(address user) internal {
        uint256 staked = stakedBalance[user];
        if (staked > 0 && rewardPerTokenPerSecond > 0) {
            uint256 elapsed = block.timestamp - _rewardLastUpdate[user];
            if (elapsed > 0) {
                _accruedRewards[user] += (staked * rewardPerTokenPerSecond * elapsed) / 1e18;
            }
        }
        _rewardLastUpdate[user] = block.timestamp;
    }
}

contracts/PayPerView.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title PayPerView
 * @author Decentralflix — Phase 2
 * @notice One-time film purchases. Filmmakers register their own films and set
 * prices; buyers pay the EXACT price (under- or overpayment reverts — there are
 * no refunds and no partial credit) and receive permanent access. Revenue
 * accrues per film in the contract; the filmmaker withdraws it, at which point
 * a platform fee (basis points, owner-set, hard-capped at 25%) is split off to
 * the platform. Platform fees are withdrawn separately by the owner.
 * @dev Utility/access tokens only. No investment contract, no promised returns.
 * Any mainnet deployment must be reviewed by licensed counsel first.
 */
contract PayPerView is Ownable, ReentrancyGuard {
    /// @notice A purchasable film.
    struct Film {
        address filmmaker; // set at registration to msg.sender; receives revenue
        uint256 priceWei; // exact purchase price in wei (0 = free film)
        bool exists; // registration guard
    }

    /// @notice Hard cap on the platform fee: 2500 bps = 25%.
    uint256 public constant MAX_PLATFORM_FEE_BPS = 2500;

    // ── Errors ────────────────────────────────────────────────────────────
    error InvalidFilmId();
    error FilmAlreadyRegistered(uint256 filmId);
    error FilmNotFound(uint256 filmId);
    error NotFilmmaker(uint256 filmId, address caller);
    error IncorrectPayment(uint256 expected, uint256 received);
    error NoRevenue(uint256 filmId);
    error NoPlatformFees();
    error FeeTooHigh(uint256 requestedBps, uint256 maxBps);
    error TransferFailed();

    // ── Events ────────────────────────────────────────────────────────────
    event FilmRegistered(uint256 indexed filmId, address indexed filmmaker, uint256 priceWei);
    event FilmPriceUpdated(uint256 indexed filmId, uint256 oldPrice, uint256 newPrice);
    event AccessPurchased(uint256 indexed filmId, address indexed buyer, uint256 pricePaid);
    event RevenueWithdrawn(
        uint256 indexed filmId,
        address indexed filmmaker,
        uint256 filmmakerAmount,
        uint256 platformFee
    );
    event PlatformFeesWithdrawn(address indexed owner, uint256 amount);
    event PlatformFeeUpdated(uint256 oldFeeBps, uint256 newFeeBps);

    /// @notice Platform fee in basis points (10000 = 100%). Capped at 2500.
    uint256 public platformFeeBps;

    mapping(uint256 => Film) private _films; // filmId => Film
    mapping(uint256 => mapping(address => bool)) private _access; // filmId => buyer => permanent access
    mapping(uint256 => uint256) private _filmRevenue; // filmId => accrued wei awaiting withdrawal
    uint256 private _accruedPlatformFees; // wei of platform fees awaiting owner withdrawal

    constructor() Ownable(msg.sender) {}

    // ── Film registry (filmmakers) ────────────────────────────────────────

    /**
     * @notice Register a film for pay-per-view sale. The caller is recorded as
     * the filmmaker and is the only address that can update the price or
     * withdraw this film's revenue.
     * @param filmId Platform-unique film identifier (must be non-zero and unused).
     * @param priceWei Exact purchase price in wei (0 allowed for free films).
     */
    function registerFilm(uint256 filmId, uint256 priceWei) external {
        if (filmId == 0) revert InvalidFilmId();
        if (_films[filmId].exists) revert FilmAlreadyRegistered(filmId);

        _films[filmId] = Film({filmmaker: msg.sender, priceWei: priceWei, exists: true});

        emit FilmRegistered(filmId, msg.sender, priceWei);
    }

    /// @notice Update the purchase price. Only the film's filmmaker may call.
    function setFilmPrice(uint256 filmId, uint256 newPrice) external {
        Film storage film = _getFilmOrRevert(filmId);
        if (film.filmmaker != msg.sender) revert NotFilmmaker(filmId, msg.sender);

        uint256 oldPrice = film.priceWei;
        film.priceWei = newPrice;

        emit FilmPriceUpdated(filmId, oldPrice, newPrice);
    }

    // ── Purchase ──────────────────────────────────────────────────────────

    /**
     * @notice Buy permanent access to a film. Payment must equal the film's
     * current price EXACTLY — overpayment is not refunded, it reverts.
     * Revenue accrues in the contract until the filmmaker withdraws it.
     */
    function buyAccess(uint256 filmId) external payable nonReentrant {
        Film memory film = _getFilmOrRevert(filmId);
        if (msg.value != film.priceWei) revert IncorrectPayment(film.priceWei, msg.value);

        _access[filmId][msg.sender] = true;
        _filmRevenue[filmId] += msg.value;

        emit AccessPurchased(filmId, msg.sender, msg.value);
    }

    // ── Withdrawals ───────────────────────────────────────────────────────

    /**
     * @notice Withdraw this film's accrued revenue to the filmmaker. The platform
     * fee (`platformFeeBps`) is split off and credited to the platform balance.
     * Only the film's filmmaker may call.
     */
    function withdrawRevenue(uint256 filmId) external nonReentrant {
        Film memory film = _getFilmOrRevert(filmId);
        if (film.filmmaker != msg.sender) revert NotFilmmaker(filmId, msg.sender);

        uint256 amount = _filmRevenue[filmId];
        if (amount == 0) revert NoRevenue(filmId);
        _filmRevenue[filmId] = 0;

        uint256 fee = (amount * platformFeeBps) / 10000;
        _accruedPlatformFees += fee;
        uint256 filmmakerAmount = amount - fee;

        (bool ok, ) = film.filmmaker.call{value: filmmakerAmount}("");
        if (!ok) revert TransferFailed();

        emit RevenueWithdrawn(filmId, film.filmmaker, filmmakerAmount, fee);
    }

    /// @notice Withdraw all accrued platform fees to the owner.
    function withdrawPlatformFees() external onlyOwner nonReentrant {
        uint256 amount = _accruedPlatformFees;
        if (amount == 0) revert NoPlatformFees();
        _accruedPlatformFees = 0;

        (bool ok, ) = owner().call{value: amount}("");
        if (!ok) revert TransferFailed();

        emit PlatformFeesWithdrawn(owner(), amount);
    }

    /**
     * @notice Set the platform fee in basis points. Hard-capped at 2500 (25%).
     * Applies to revenue withdrawn after the change; already-withdrawn revenue
     * is unaffected.
     */
    function setPlatformFeeBps(uint256 newFeeBps) external onlyOwner {
        if (newFeeBps > MAX_PLATFORM_FEE_BPS) {
            revert FeeTooHigh(newFeeBps, MAX_PLATFORM_FEE_BPS);
        }
        uint256 oldFeeBps = platformFeeBps;
        platformFeeBps = newFeeBps;
        emit PlatformFeeUpdated(oldFeeBps, newFeeBps);
    }

    // ── Views ─────────────────────────────────────────────────────────────

    /// @notice True if `user` has purchased permanent access to `filmId`.
    function hasAccess(address user, uint256 filmId) external view returns (bool) {
        return _access[filmId][user];
    }

    /// @notice Full metadata for a registered film. Reverts if unregistered.
    function getFilm(uint256 filmId) external view returns (Film memory) {
        return _getFilmOrRevert(filmId);
    }

    /// @notice Revenue accrued for `filmId` but not yet withdrawn by the filmmaker.
    function filmRevenue(uint256 filmId) external view returns (uint256) {
        return _filmRevenue[filmId];
    }

    /// @notice Platform fees accrued but not yet withdrawn by the owner.
    function accruedPlatformFees() external view returns (uint256) {
        return _accruedPlatformFees;
    }

    function _getFilmOrRevert(uint256 filmId) internal view returns (Film storage) {
        Film storage film = _films[filmId];
        if (!film.exists) revert FilmNotFound(filmId);
        return film;
    }
}

contracts/SubscriptionManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SubscriptionManager
 * @author Decentralflix — Phase 2
 * @notice Time-based recurring access passes. The owner creates plans
 * (name, price, duration); users subscribe with exact payment, renew an active
 * subscription to extend it, or cancel to end it immediately (no refunds).
 * All payments accumulate in the contract; only the owner can withdraw.
 * @dev Utility/access tokens only. No investment contract, no promised returns.
 * Any mainnet deployment must be reviewed by licensed counsel first.
 */
contract SubscriptionManager is Ownable, ReentrancyGuard {
    /// @notice A purchasable access plan.
    struct Plan {
        string name; // plan display name
        uint256 priceWei; // exact subscription/renewal price in wei
        uint256 durationSecs; // how long one purchase lasts
        bool active; // false => new subscriptions/renewals blocked
        bool exists; // creation guard
    }

    /// @notice One user's current subscription state.
    struct Subscription {
        uint256 planId; // plan the subscription is on
        uint256 expiresAt; // unix timestamp; active while > block.timestamp
    }

    // ── Errors ────────────────────────────────────────────────────────────
    error PlanAlreadyExists(uint256 planId);
    error PlanNotFound(uint256 planId);
    error PlanInactive(uint256 planId);
    error EmptyName();
    error ZeroPrice();
    error ZeroDuration();
    error IncorrectPayment(uint256 expected, uint256 received);
    error AlreadySubscribed(address holder);
    error SubscriptionNotActive(address holder);
    error PlanMismatch(uint256 currentPlanId, uint256 requestedPlanId);
    error NoSubscription(address holder);
    error NoFundsToWithdraw();
    error WithdrawFailed();

    // ── Events ────────────────────────────────────────────────────────────
    event PlanCreated(uint256 indexed planId, string name, uint256 priceWei, uint256 durationSecs);
    event PlanDeactivated(uint256 indexed planId);
    event Subscribed(address indexed holder, uint256 indexed planId, uint256 expiresAt);
    event Renewed(address indexed holder, uint256 indexed planId, uint256 newExpiresAt);
    event Cancelled(address indexed holder, uint256 indexed planId);
    event Withdrawn(address indexed owner, uint256 amount);

    mapping(uint256 => Plan) private _plans; // planId => Plan
    mapping(address => Subscription) private _subscriptions; // holder => Subscription

    constructor() Ownable(msg.sender) {}

    // ── Plan management (owner only) ──────────────────────────────────────

    /**
     * @notice Create a subscription plan.
     * @param planId Platform-unique plan identifier (must be unused).
     * @param name Plan display name (non-empty).
     * @param priceWei Exact price per subscription period in wei (must be > 0).
     * @param durationSecs Length of one subscription period in seconds (must be > 0).
     */
    function createPlan(
        uint256 planId,
        string calldata name,
        uint256 priceWei,
        uint256 durationSecs
    ) external onlyOwner {
        if (_plans[planId].exists) revert PlanAlreadyExists(planId);
        if (bytes(name).length == 0) revert EmptyName();
        if (priceWei == 0) revert ZeroPrice();
        if (durationSecs == 0) revert ZeroDuration();

        _plans[planId] = Plan({
            name: name,
            priceWei: priceWei,
            durationSecs: durationSecs,
            active: true,
            exists: true
        });

        emit PlanCreated(planId, name, priceWei, durationSecs);
    }

    /**
     * @notice Deactivate a plan. Existing active subscriptions keep working until
     * they expire, but new subscriptions and renewals are blocked.
     */
    function deactivatePlan(uint256 planId) external onlyOwner {
        Plan storage plan = _getPlanOrRevert(planId);
        plan.active = false;
        emit PlanDeactivated(planId);
    }

    // ── Subscriptions ─────────────────────────────────────────────────────

    /**
     * @notice Start a subscription. Requires no currently active subscription
     * (cancel or let it expire first) and exact payment of the plan price.
     */
    function subscribe(uint256 planId) external payable nonReentrant {
        Plan memory plan = _getPlanOrRevert(planId);
        if (!plan.active) revert PlanInactive(planId);
        if (hasActiveSubscription(msg.sender)) revert AlreadySubscribed(msg.sender);
        if (msg.value != plan.priceWei) revert IncorrectPayment(plan.priceWei, msg.value);

        uint256 expiresAt = block.timestamp + plan.durationSecs;
        _subscriptions[msg.sender] = Subscription({planId: planId, expiresAt: expiresAt});

        emit Subscribed(msg.sender, planId, expiresAt);
    }

    /**
     * @notice Extend an active subscription by one plan period. Must be called
     * while the subscription is still active and for the same plan the
     * subscription is on.
     */
    function renew(uint256 planId) external payable nonReentrant {
        Subscription storage sub = _subscriptions[msg.sender];
        if (sub.expiresAt <= block.timestamp) revert SubscriptionNotActive(msg.sender);
        if (sub.planId != planId) revert PlanMismatch(sub.planId, planId);

        Plan memory plan = _getPlanOrRevert(planId);
        if (!plan.active) revert PlanInactive(planId);
        if (msg.value != plan.priceWei) revert IncorrectPayment(plan.priceWei, msg.value);

        sub.expiresAt += plan.durationSecs;

        emit Renewed(msg.sender, planId, sub.expiresAt);
    }

    /**
     * @notice End the caller's subscription immediately. No refund is issued;
     * already-paid time is forfeited.
     */
    function cancel() external {
        if (!hasActiveSubscription(msg.sender)) revert NoSubscription(msg.sender);
        uint256 planId = _subscriptions[msg.sender].planId;
        _subscriptions[msg.sender].expiresAt = block.timestamp;
        emit Cancelled(msg.sender, planId);
    }

    /// @notice Withdraw all accumulated subscription revenue to the owner.
    function withdraw() external onlyOwner nonReentrant {
        uint256 amount = address(this).balance;
        if (amount == 0) revert NoFundsToWithdraw();
        (bool ok, ) = owner().call{value: amount}("");
        if (!ok) revert WithdrawFailed();
        emit Withdrawn(owner(), amount);
    }

    // ── Views ─────────────────────────────────────────────────────────────

    /// @notice True if `holder` has a subscription with `expiresAt > block.timestamp`.
    function hasActiveSubscription(address holder) public view returns (bool) {
        return _subscriptions[holder].expiresAt > block.timestamp;
    }

    /// @notice Returns the plan ID and expiry timestamp of `holder`'s subscription.
    function subscriptionOf(address holder)
        external
        view
        returns (uint256 planId, uint256 expiresAt)
    {
        Subscription memory sub = _subscriptions[holder];
        return (sub.planId, sub.expiresAt);
    }

    /// @notice Full metadata for a plan. Reverts if the plan does not exist.
    function getPlan(uint256 planId) external view returns (Plan memory) {
        return _getPlanOrRevert(planId);
    }

    function _getPlanOrRevert(uint256 planId) internal view returns (Plan storage) {
        Plan storage plan = _plans[planId];
        if (!plan.exists) revert PlanNotFound(planId);
        return plan;
    }
}

contracts/TicketNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title TicketNFT
 * @author Decentralflix — Phase 2
 * @notice ERC721 movie tickets. Each film is registered once by the platform owner;
 * buyers mint single tickets by paying the film's exact price, which is forwarded
 * directly to the filmmaker. Tickets are transferable by default, but a film can be
 * flagged `soulbound` at registration to make its tickets non-transferable
 * (mint and burn still work). A ticket is single-use: `redeemTicket` burns it on
 * entry, after which `hasValidTicket` returns false.
 * @dev Utility/access tokens only. No investment contract, no promised returns.
 * Any mainnet deployment must be reviewed by licensed counsel first.
 */
contract TicketNFT is ERC721, Ownable, ReentrancyGuard {
    using Strings for uint256;

    /// @notice Metadata for one registered film.
    struct Film {
        string title; // human-readable title
        uint256 priceWei; // exact mint price in wei (0 = free film)
        address filmmaker; // receives mint payments
        bool active; // false => minting disabled (redemption still works)
        bool soulbound; // true => tickets cannot be transferred
        string metadataURI; // base URI used to build tokenURI
        bool exists; // registration guard
    }

    // ── Errors ────────────────────────────────────────────────────────────
    error InvalidFilmId();
    error FilmAlreadyRegistered(uint256 filmId);
    error FilmNotFound(uint256 filmId);
    error FilmInactive(uint256 filmId);
    error EmptyTitle();
    error ZeroAddress();
    error IncorrectPayment(uint256 expected, uint256 received);
    error SoulboundTransferBlocked(uint256 tokenId);
    error NotTicketOwner(uint256 tokenId, address caller);
    error PaymentFailed();

    // ── Events ────────────────────────────────────────────────────────────
    event FilmRegistered(
        uint256 indexed filmId,
        string title,
        uint256 priceWei,
        address indexed filmmaker,
        bool soulbound
    );
    event FilmStatusChanged(uint256 indexed filmId, bool active);
    event FilmPriceUpdated(uint256 indexed filmId, uint256 oldPrice, uint256 newPrice);
    event TicketMinted(
        uint256 indexed tokenId,
        uint256 indexed filmId,
        address indexed buyer,
        uint256 pricePaid
    );
    event TicketRedeemed(uint256 indexed tokenId, uint256 indexed filmId, address indexed holder);

    uint256 private _nextTokenId = 1;

    mapping(uint256 => Film) private _films; // filmId => Film
    mapping(uint256 => uint256) private _ticketFilm; // tokenId => filmId
    mapping(uint256 => mapping(address => uint256)) private _validTickets; // filmId => holder => unredeemed count

    constructor() ERC721("Decentralflix Ticket", "DFLIX-TIX") Ownable(msg.sender) {}

    // ── Film registry (owner only) ────────────────────────────────────────

    /**
     * @notice Register a film so tickets can be minted for it.
     * @param filmId Platform-unique film identifier (must be non-zero and unused).
     * @param title Film title (non-empty).
     * @param priceWei Exact ticket price in wei (0 allowed for free films).
     * @param filmmaker Address that receives mint payments (non-zero).
     * @param soulbound If true, tickets for this film cannot be transferred.
     * @param metadataURI Base URI for token metadata (may be empty).
     */
    function registerFilm(
        uint256 filmId,
        string calldata title,
        uint256 priceWei,
        address filmmaker,
        bool soulbound,
        string calldata metadataURI
    ) external onlyOwner {
        if (filmId == 0) revert InvalidFilmId();
        if (_films[filmId].exists) revert FilmAlreadyRegistered(filmId);
        if (bytes(title).length == 0) revert EmptyTitle();
        if (filmmaker == address(0)) revert ZeroAddress();

        _films[filmId] = Film({
            title: title,
            priceWei: priceWei,
            filmmaker: filmmaker,
            active: true,
            soulbound: soulbound,
            metadataURI: metadataURI,
            exists: true
        });

        emit FilmRegistered(filmId, title, priceWei, filmmaker, soulbound);
    }

    /**
     * @notice Enable or disable minting for a film. Redemption of already-minted
     * tickets is unaffected.
     */
    function setFilmActive(uint256 filmId, bool active) external onlyOwner {
        Film storage film = _getFilmOrRevert(filmId);
        film.active = active;
        emit FilmStatusChanged(filmId, active);
    }

    /// @notice Update a film's ticket price. Does not affect already-minted tickets.
    function setFilmPrice(uint256 filmId, uint256 newPrice) external onlyOwner {
        Film storage film = _getFilmOrRevert(filmId);
        uint256 oldPrice = film.priceWei;
        film.priceWei = newPrice;
        emit FilmPriceUpdated(filmId, oldPrice, newPrice);
    }

    // ── Minting / redemption ──────────────────────────────────────────────

    /**
     * @notice Mint one ticket for `filmId`. Requires exact payment of the film's
     * current price; the full amount is forwarded to the filmmaker. No platform
     * fee is taken here.
     * @return tokenId The newly minted ticket's token ID.
     */
    function mintTicket(uint256 filmId) external payable nonReentrant returns (uint256 tokenId) {
        Film memory film = _getFilmOrRevert(filmId);
        if (!film.active) revert FilmInactive(filmId);
        if (msg.value != film.priceWei) revert IncorrectPayment(film.priceWei, msg.value);

        tokenId = _nextTokenId;
        _nextTokenId += 1;

        _ticketFilm[tokenId] = filmId;
        _validTickets[filmId][msg.sender] += 1;
        _safeMint(msg.sender, tokenId);

        emit TicketMinted(tokenId, filmId, msg.sender, msg.value);

        if (msg.value > 0) {
            (bool ok, ) = film.filmmaker.call{value: msg.value}("");
            if (!ok) revert PaymentFailed();
        }
    }

    /**
     * @notice Burn a ticket on entry. Only the ticket's current owner can redeem.
     * A redeemed ticket no longer counts toward `hasValidTicket`.
     */
    function redeemTicket(uint256 tokenId) external nonReentrant {
        address owner = _requireOwned(tokenId);
        if (owner != msg.sender) revert NotTicketOwner(tokenId, msg.sender);

        uint256 filmId = _ticketFilm[tokenId];
        _burn(tokenId);
        _validTickets[filmId][owner] -= 1;

        emit TicketRedeemed(tokenId, filmId, owner);
    }

    // ── Views ─────────────────────────────────────────────────────────────

    /// @notice True if `holder` owns at least one unredeemed ticket for `filmId`.
    function hasValidTicket(address holder, uint256 filmId) external view returns (bool) {
        return _validTickets[filmId][holder] > 0;
    }

    /// @notice Number of unredeemed tickets `holder` owns for `filmId`.
    function validTicketCount(address holder, uint256 filmId) external view returns (uint256) {
        return _validTickets[filmId][holder];
    }

    /// @notice The film a ticket was minted for.
    function ticketFilm(uint256 tokenId) external view returns (uint256) {
        _requireOwned(tokenId);
        return _ticketFilm[tokenId];
    }

    /// @notice Full metadata for a registered film. Reverts if unregistered.
    function getFilm(uint256 filmId) external view returns (Film memory) {
        return _getFilmOrRevert(filmId);
    }

    /// @notice Next token ID that will be minted (informational).
    function nextTokenId() external view returns (uint256) {
        return _nextTokenId;
    }

    /**
     * @dev Builds `<metadataURI>/<tokenId>` when the film registered a base URI,
     * otherwise returns an empty string.
     */
    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        string memory base = _films[_ticketFilm[tokenId]].metadataURI;
        if (bytes(base).length == 0) return "";
        return string.concat(base, "/", tokenId.toString());
    }

    // ── Soulbound enforcement ─────────────────────────────────────────────

    /**
     * @dev Blocks transfers (not mints or burns) for films flagged soulbound.
     * @param to Recipient; `address(0)` on burn, `from` is `address(0)` on mint.
     */
    function _update(address to, uint256 tokenId, address auth)
        internal
        override
        returns (address)
    {
        address from = _ownerOf(tokenId);
        if (from != address(0) && to != address(0)) {
            if (_films[_ticketFilm[tokenId]].soulbound) {
                revert SoulboundTransferBlocked(tokenId);
            }
        }
        return super._update(to, tokenId, auth);
    }

    function _getFilmOrRevert(uint256 filmId) internal view returns (Film storage) {
        Film storage film = _films[filmId];
        if (!film.exists) revert FilmNotFound(filmId);
        return film;
    }
}

